      "Un rostro surrealista fusionado con capas de ojos y una mariposa, pintado con aerosol sobre una pared de 5 por 3 metros en Malmö, Suecia. Se pintó en vivo durante el Meeting of Styles, el festival internacional de graffiti y arte urbano que reúne a escritores y muralistas desde los años noventa. El rostro está construido con planos de color superpuestos en lugar de contornos, así que los ojos se leen como varias caras a la vez según la distancia desde la que se mire."
