    "body": [
      "Pintado para el Emush Mural Event, en el fin del mundo, Ushuaia, Tierra del Fuego, la punta más austral de Argentina. La idea arrancó como un pingüino local, pero quería hacerlo único y argentino: un rey. En el mazo de cartas españolas que se usa para el Truco, el rey es el 12, así que el pingüino se convirtió en el 12, coronado, envuelto en una capa con los colores de la bandera argentina, sosteniendo una moneda con un pingüino bebé grabado. El nombre, \"El Rey de Reyes\", es un guiño al año anterior a la pintada del mural, cuando Argentina salió campeona del mundo en fútbol. Y la mañana que empecé a pintar, un Pingüino Emperador, una especie que casi nunca se ve tan lejos de la Antártida, apareció en la bahía de Ushuaia, como si la pared ya supiera en qué se quería convertir."
    ],
